function power(){return 18+data.level*4+(data.items.find(i=>i.id===data.equipped)?.power||0);}function maxhp(){return 100+data.level*12;}
let hp=maxhp(),mana=100,running=false,dead=false,kills=0,bossSpawned=false,boss=null,elapsed=0,invulnerable=0;const enemies=[],shots=[],effects=[],drops=[],keys=new Set(),cd={fire:0,ice:0,blink:0,heal:0};let aim=new T.Vector3(0,0,-1),aimManual=false,fireHeld=false;const joy={x:0,y:0,id:null};let noteTime=0;
function notice(msg){$('notice').textContent=msg;noteTime=3;}
function valid(x,z){return Math.abs(x)<23&&Math.abs(z)<23&&(!environment||environment.walkable(x,z))&&!obstacles.some(o=>Math.hypot(x-o.x,z-o.z)<o.r+.4);}
function move(o,dx,dz){const oldX=o.position.x,oldZ=o.position.z;if(valid(o.position.x+dx,o.position.z))o.position.x+=dx;if(valid(o.position.x,o.position.z+dz))o.position.z+=dz;return Math.hypot(o.position.x-oldX,o.position.z-oldZ);}
