function spawn(b=false){let x,z;do{x=(Math.random()-.5)*40;z=(Math.random()-.5)*40;}while(!valid(x,z)||Math.hypot(x-player.position.x,z-player.position.z)<8);if(b){x=0;z=-15;}const g=character(true,b);g.position.set(x,0,z);const e={g,hp:b?650+data.clears*120:40+data.clears*8,max:b?650+data.clears*120:40+data.clears*8,speed:b?1.4:1.6+Math.random()*.6,boss:b,slow:0,attack:0,pulse:3};enemies.push(e);return e;}
