function target(){return enemies.reduce((a,e)=>!a||e.g.position.distanceToSquared(player.position)<a.g.position.distanceToSquared(player.position)?e:a,null);}
function cast(skill){if(!running||cd[skill]>0)return;if(skill==='fire'){mage?.cast();const e=target();if(!aimManual&&e)aim.copy(e.g.position).sub(player.position).setY(0).normalize();const g=mesh(new T.SphereGeometry(.2,8,8),new T.MeshBasicMaterial({color:0xffa353}),player.position.x,.9,player.position.z);shots.push({g,dir:aim.clone(),age:0});cd.fire=.34;player.rotation.y=Math.atan2(aim.x,aim.z);}if(skill==='ice'){if(mana<30){notice('法力不足');return;}mana-=30;mage?.cast();cd.ice=5;fx(player.position.x,player.position.z,0x9bdfff,6);for(const e of [...enemies])if(e.g.position.distanceTo(player.position)<6){e.slow=3;damage(e,power()*1.6);}}if(skill==='blink'){if(mana<20){notice('法力不足');return;}mana-=20;cd.blink=3;fx(player.position.x,player.position.z,0xb7a4ff,2);let dir=new T.Vector3(joy.x,0,joy.y);if(dir.length()<.1)dir.set((keys.has('d')?1:0)-(keys.has('a')?1:0),0,(keys.has('s')?1:0)-(keys.has('w')?1:0));if(dir.length()<.1)dir.copy(aim);dir.normalize();for(let i=0;i<20;i++)move(player,dir.x*.3,dir.z*.3);invulnerable=.6;fx(player.position.x,player.position.z,0xb7a4ff,2);}if(skill==='heal'){if(hp>=maxhp())return;hp=Math.min(maxhp(),hp+maxhp()*.55);cd.heal=12;fx(player.position.x,player.position.z,0xf79280,2);}}
function finish(win){running=false;fireHeld=false;$('resulttag').textContent=win?'地窟已净化':'火种尚未熄灭';$('resulttitle').textContent=win?'灰烬之下，新的力量':'在余烬中重生';$('resultdesc').textContent=win?'击败了灰烬领主，装备与等级已保留。下一轮敌人将更强，法杖词缀也会成长。':'等级与已拾取装备保留。尝试用冰霜新星减速，闪现拉开距离；药水可反复使用。';$('result').showModal();}
