function reset(){clearEncounter();scenery();player.position.set(0,0,7);hp=maxhp();mana=100;kills=0;bossSpawned=false;boss=null;elapsed=0;dead=false;for(const s in cd)cd[s]=0;keys.clear();joy.x=joy.y=0;running=true;$('bossbar').hidden=true;for(let i=0;i<12;i++)spawn();notice('灰烬地窟 · 击败 12 名守卫');}
function inventory(){running=false;fireHeld=false;$('stats').textContent='Lv. '+data.level+' · 法术伤害 '+power()+' · 生命 '+maxhp()+' · 已净化 '+data.clears+' 次';$('items').replaceChildren();if(!data.items.length)$('items').textContent='尚无装备。击败怪物并靠近发光法杖拾取。';for(const item of [...data.items].sort((a,b)=>b.power-a.power)){const row=document.createElement('div');row.className='item';const text=document.createElement('div'),name=document.createElement('strong'),sub=document.createElement('small');name.textContent=item.name;name.style.color=['#c1c2b6','#7cc9ff','#e6b35b'][item.rarity]||'#c1c2b6';sub.textContent='法术伤害 +'+item.power;text.append(name,sub);const equip=document.createElement('button');equip.textContent=data.equipped===item.id?'已装备':'装备';equip.disabled=data.equipped===item.id;equip.onclick=()=>{data.equipped=item.id;save();inventory();};const dismantle=document.createElement('button');dismantle.textContent='分解';dismantle.disabled=data.equipped===item.id;dismantle.onclick=()=>{data.items=data.items.filter(i=>i.id!==item.id);save();inventory();};row.append(text,equip,dismantle);$('items').append(row);}if(!$('inventory').open)$('inventory').showModal();}
function resume(){keys.clear();fireHeld=false;if(!dead&&!$('intro').open&&!$('result').open&&!$('inventory').open&&!$('character').open&&!$('save-dialog').open)running=true;}
$('bag').onclick=()=>{if(running)inventory();};$('closebag').onclick=()=>$('inventory').close();$('inventory').addEventListener('close',resume);$('intro').addEventListener('cancel',e=>e.preventDefault());$('result').addEventListener('cancel',e=>e.preventDefault());$('start').onclick=()=>{$('intro').close();reset();};$('retry').onclick=()=>{$('result').close();reset();};
for(const b of document.querySelectorAll('[data-skill]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);aimManual=false;if(b.dataset.skill==='fire')fireHeld=true;cast(b.dataset.skill);};b.onpointerup=b.onpointercancel=()=>fireHeld=false;}
window.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();const k=e.key.toLowerCase();keys.add(k);if(e.repeat)return;if(k==='1'){aimManual=false;fireHeld=true;}if(k==='2')cast('ice');if(k===' ')cast('blink');if(k==='3')cast('heal');if(k==='b'&&running)inventory();});window.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());if(e.key==='1')fireHeld=false;});window.addEventListener('blur',()=>{keys.clear();fireHeld=false;joy.x=joy.y=0;});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)inventory();});
const ray=new T.Raycaster(),plane=new T.Plane(new T.Vector3(0,1,0),0),hit=new T.Vector3();$('world').onpointermove=e=>{if(e.pointerType==='touch')return;ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1),camera);if(ray.ray.intersectPlane(plane,hit)){aim.copy(hit).sub(player.position).setY(0).normalize();aimManual=true;}};$('world').onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button===0){fireHeld=true;cast('fire');}};window.addEventListener('pointerup',()=>fireHeld=false);
const stick=$('joystick');stick.onpointerdown=e=>{joy.id=e.pointerId;stick.setPointerCapture(e.pointerId);updateJoy(e);};function updateJoy(e){if(joy.id!==e.pointerId)return;const r=stick.getBoundingClientRect();let x=(e.clientX-r.left-r.width/2)/38,y=(e.clientY-r.top-r.height/2)/38,l=Math.hypot(x,y);if(l>1){x/=l;y/=l;}joy.x=x;joy.y=y;stick.firstElementChild.style.transform=`translate(${x*30}px,${y*30}px)`;}stick.onpointermove=updateJoy;stick.onpointerup=stick.onpointercancel=()=>{joy.id=null;joy.x=joy.y=0;stick.firstElementChild.style.transform='';};
function hud(){const percent=(id,n,max)=>$(id).style.width=clamp(n/max*100,0,100)+'%';percent('hp',hp,maxhp());percent('mana',mana,100);percent('xp',data.xp,data.level*50);$('hptext').textContent=Math.ceil(hp)+' / '+maxhp();$('manatext').textContent=Math.floor(mana)+' / 100';$('level').textContent='Lv. '+data.level;for(const b of document.querySelectorAll('[data-skill]'))b.querySelector('em').textContent=cd[b.dataset.skill]>.1?cd[b.dataset.skill].toFixed(1):'';$('objective').textContent=bossSpawned?'击败灰烬领主':'净化徘徊者';$('progress').textContent=bossSpawned?'领主已苏醒 · 小心红色预警圈':Math.min(kills,12)+' / 12 守卫 · 靠近战利品自动拾取';if(boss&&boss.hp>0)$('bossbar').querySelector('i').style.width=boss.hp/boss.max*100+'%';}
const clock=new T.Clock();function tick(){requestAnimationFrame(tick);const dt=Math.min(clock.getDelta(),.04);if(running){elapsed+=dt;invulnerable-=dt;for(const s in cd)cd[s]=Math.max(0,cd[s]-dt);mana=Math.min(100,mana+dt*7);let dx=joy.x+(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),dz=joy.y+(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0),l=Math.hypot(dx,dz);if(l>1){dx/=l;dz/=l;}move(player,dx*dt*5,dz*dt*5);if(l>.1)player.rotation.y=Math.atan2(dx,dz);if(fireHeld)cast('fire');for(const e of [...enemies]){e.slow-=dt;e.attack-=dt;const v=player.position.clone().sub(e.g.position),d=v.length();v.normalize();e.g.rotation.y=Math.atan2(v.x,v.z);if(d>1.3)pursue(e.g,v.x*dt*e.speed*(e.slow>0?.3:1),v.z*dt*e.speed*(e.slow>0?.3:1));if(d<1.7&&e.attack<=0){if(invulnerable<=0)hp-=e.boss?20:8;e.attack=1.1;}if(e.boss){e.pulse-=dt;if(e.pulse<=0){fx(e.g.position.x,e.g.position.z,0xfc5545,6);e.pulse=4;e.blast=.65;e.blastPos=e.g.position.clone();}if(e.blast>0){e.blast-=dt;if(e.blast<=0){fx(e.blastPos.x,e.blastPos.z,0xff9955,6);if(e.blastPos.distanceTo(player.position)<6&&invulnerable<=0)hp-=30;}}}}for(const s of [...shots]){s.age+=dt;s.g.position.addScaledVector(s.dir,dt*16);const e=enemies.find(e=>e.g.position.distanceTo(new T.Vector3(s.g.position.x,0,s.g.position.z))<(e.boss?1.5:.65));if(e)damage(e,power());if(e||s.age>1.8||!valid(s.g.position.x,s.g.position.z)){removeObject(s.g);shots.splice(shots.indexOf(s),1);}}for(const d of [...drops]){d.g.rotation.y+=dt;d.g.position.y=.5+Math.sin(elapsed*3)*.12;if(d.g.position.distanceTo(player.position)<1.8)collect(d);}if(kills>=12&&!bossSpawned&&running){bossSpawned=true;boss=spawn(true);$('bossbar').hidden=false;notice('灰烬领主已苏醒');}if(hp<=0){hp=0;dead=true;save();finish(false);}}for(const e of [...effects]){e.age+=dt;e.g.scale.setScalar(e.r*e.age/e.life);e.g.material.opacity=1-e.age/e.life;if(e.age>e.life){scene.remove(e.g);e.g.geometry.dispose();e.g.material.dispose();effects.splice(effects.indexOf(e),1);}}if(noteTime>0){noteTime-=dt;if(noteTime<=0)$('notice').textContent='';}environment?.update(dt,elapsed,player.position);const moving=running&&(Math.abs(joy.x)+Math.abs(joy.y)>0.1||[...keys].some(k=>['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)));mage?.update(running?dt:0,moving);camera.position.lerp(new T.Vector3(player.position.x,16,player.position.z+14),.09);camera.lookAt(player.position.x,0,player.position.z-1);hud();worldRenderer.render(scene);}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();worldRenderer.resize();}window.addEventListener('resize',resize);resize();scenery();player.position.set(0,0,7);camera.position.set(0,16,21);if(data.level>1||data.items.length)$('savehint').textContent='继续本机存档 · Lv. '+data.level+' · '+data.items.length+' 件装备';$('intro').showModal();tick();

$('hero').disabled=true;
$('hero').onclick=()=>{if(!mage||$('intro').open||$('result').open)return;heroWasRunning=running;running=false;fireHeld=false;keys.clear();$('character').showModal();stopPreview=mage.preview($('model-preview'));};
$('closehero').onclick=()=>$('character').close();
$('character').addEventListener('close',()=>{stopPreview?.();stopPreview=null;running=heroWasRunning&&!dead&&!$('intro').open&&!$('result').open&&!$('inventory').open&&!$('save-dialog').open;});
loadMage(player).then(actor=>{mage=actor;$('start').disabled=false;$('start').innerHTML='进入灰烬地窟 <span>→</span>';$('hero').disabled=false;}).catch(error=>{console.error('Mage model load failed',error);$('start').textContent='模型加载失败';$('savehint').textContent='请刷新页面重试，或检查模型资源是否可访问。';});

function pauseForSave(){const wasRunning=running;running=false;fireHeld=false;keys.clear();joy.x=joy.y=0;joy.id=null;$('joystick').firstElementChild.style.transform='';return wasRunning;}
function applySavedCharacter(nextData){
 running=false;fireHeld=false;keys.clear();joy.x=joy.y=0;joy.id=null;
 for(const id of ['inventory','character','result'])if($(id).open)$(id).close();
 running=false;clearEncounter();data=nextData;hp=maxhp();mana=100;kills=0;bossSpawned=false;boss=null;elapsed=0;dead=false;invulnerable=0;
 for(const skill in cd)cd[skill]=0;player.position.set(0,0,7);$('bossbar').hidden=true;
 $('savehint').textContent='继续本机存档 · Lv. '+data.level+' · '+data.items.length+' 件装备';
 if(!$('intro').open)$('intro').showModal();hud();
}
savePanel=createSavePanel({manager:saveManager,getData:()=>data,onPause:pauseForSave,onResume:(wasRunning,changed)=>{keys.clear();fireHeld=false;if(wasRunning&&!changed)resume();},onApplyData:applySavedCharacter,notify:notice});
